import itertools, json, sys

L = {71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64}

# Precompute all possible triples (a,b,c) with a<b and a+b=c
triples = []
for a, b in itertools.combinations(L, 2):
    c = a + b
    if c in L and c != a and c != b:
        triples.append((a, b, c))

# Backtracking search for exact cover of L with 15 triples
solution = []
used = set()

def backtrack(start):
    if len(solution) == 15:
        if used == L:
            return True
        return False
    # prune if not enough remaining numbers
    if len(L) - len(used) < 3 * (15 - len(solution)):
        return False
    for idx in range(start, len(triples)):
        a, b, c = triples[idx]
        if a in used or b in used or c in used:
            continue
        # choose
        solution.append((a, b, c))
        used.update([a, b, c])
        if backtrack(idx + 1):
            return True
        # undo
        solution.pop()
        used.difference_update([a, b, c])
    return False

found = backtrack(0)

if found:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
else:
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "search", "search_exhausted": True, "nodes_explored": None, "method": "backtrack"}

print("WITNESS: " + json.dumps(witness))

import itertools, json, sys
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]
L_set = set(L)
# Precompute all valid triples (a,b,c) with a+b=c
triples = []
for a,b,c in itertools.permutations(L,3):
    if a + b == c:
        # enforce ordering to avoid duplicate permutations of same triple
        if a <= b:
            triples.append((a,b,c))
# Backtracking search for disjoint covering of all elements
used = set()
solution = []

def backtrack(start):
    if len(solution) == 15:
        return True
    for idx in range(start, len(triples)):
        a,b,c = triples[idx]
        if a in used or b in used or c in used:
            continue
        # choose
        used.update([a,b,c])
        solution.append((a,b,c))
        if backtrack(idx+1):
            return True
        # undo
        used.difference_update([a,b,c])
        solution.pop()
    return False

found = backtrack(0)
if found:
    witness = {"polarity": "positive", "evidence": {"path": "execution://witness"}, "data": {"triples": solution}}
    print("WITNESS: " + json.dumps(witness))
else:
    # No solution found (unlikely for this input)
    witness = {"polarity": "negative", "evidence": {"path": "execution://witness"}, "basis": "proof", "argument": "No partition exists for the given set."}
    print("WITNESS: " + json.dumps(witness))
